// TEMPORARY review probe (not part of the PR) — pr-210 scenario WITH a realistic
// production park comment ('parked-head: <sha>'). Does the park still hold?
suite('review: #633 shadowing of the walk', function () {
    var BOT_MERGE = 'b3f9c6b5b3f9c6b5b3f9c6b5b3f9c6b5b3f9c6b5';
    var RED_HEAD = '4545454545454545454545454545454545454545';
    var MAIN_TIP = '0123456789abcdef0123456789abcdef01234567';

    function vfConfig(owner, repo) {
        return { fileMap: { '../.dmtools/config.js':
            'module.exports = { repository: { owner: "' + owner + '", repo: "' + repo + '" } };' } };
    }
    function vfCli(opts) {
        return function (cmd) {
            var m = /\/commits\/([0-9a-fA-F]+)"/.exec(cmd.command);
            if (m && opts.actors && opts.actors[m[1]] !== undefined) {
                return JSON.stringify(opts.actors[m[1]]);
            }
            if (opts.parkedAt !== undefined && cmd.command.indexOf('/events?per_page=100') !== -1) {
                return '"' + opts.parkedAt + '"';
            }
            return '';
        };
    }

    test('bot merge + real park comment + NO human push since park', function () {
        var sm = makeSmAgent(Object.assign(vfConfig('a', 'b'), {
            github: {
                items: [{ key: 'pr-300', labels: ['validation_failed'], prNumber: 300,
                          draft: false, branch: 'feat/x', headSha: BOT_MERGE, author: 'guest' }],
                prStatus: { checkConclusion: 'none' },
                // THE DIFFERENCE vs pr-210: production always writes this comment
                prComments: [{ body: '🛑 validation_failed — the current head `' + RED_HEAD +
                    '` has failing checks. ... parked-head: ' + RED_HEAD }]
            },
            onCliExecute: vfCli({
                actors: (function () {
                    var map = {};
                    map[BOT_MERGE] = { login: 'ai-teammate', date: '2026-10-03T23:04:00Z',
                                       committer: 'sm-silent-update', parents: [RED_HEAD, MAIN_TIP] };
                    map[RED_HEAD] = { login: 'vendor-guest', date: '2026-10-03T22:20:00Z' };
                    return map;
                })(),
                parkedAt: '2026-10-03T22:31:00Z'
            })
        }));
        sm.action({ jobParams: { owner: 'a', repo: 'b', machineAuthor: 'ai-teammate',
                                 rules: [{ source: 'github', query: { type: 'pr', mergeState: ['BEHIND'], draft: false },
                                           localAction: 'update_branch', limit: 5, id: 'silent-update-behind' }] } });

        console.log('  >>> label removes: ' + JSON.stringify(sm.capturedPrLabelRemoves));
        console.log('  >>> comments: ' + JSON.stringify(sm.capturedPrComments.map(function (c) {
            return c.body.slice(0, 120); })));
        if (sm.capturedPrLabelRemoves.length > 0) {
            console.log('  >>> 🚨 PARK CLEARED — the #633 head-change branch shadowed the walk ' +
                '(bot merge with NO human push cleared the park)');
        } else {
            console.log('  >>> park held');
        }
    });
});

