        });
        var runs = mcpParse((res || {}).output ||
                            (res || {}).stdout || res);
        var list = (runs && runs.workflow_runs) || [];
        if (!list.length) return null;
        list.sort(function (a, b) {
            return Date.parse(b.updated_at || b.created_at || 0) -
                   Date.parse(a.updated_at || a.created_at || 0);
        });
        return list[0];
