    return function (cmd) {
        var m = /\/commits\/([0-9a-fA-Z]+)"/.exec(cmd.command);
        if (m && opts.actors && opts.actors[m[1]] !== undefined) {
            return JSON.stringify(opts.actors[m[1]]);
